<script setup>
import { ref,onMounted } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { getJSON,postJSON } from '../api'
import { roleNames } from '../auth'
import { fmtTime } from '../status'
const actionNames={setup:'初始化管理员',login:'登录',login_failed:'登录失败',logout:'退出登录',password_changed:'修改密码',user_created:'创建账号',user_updated:'调整权限',password_reset:'重置密码'}
function detailText(v){if(!v)return '—';const [role,state]=v.split(' ');return (roleNames[role]||role)+(state?(state==='enabled'?' · 启用':' · 停用'):'')}
const rows=ref([]),events=ref([]),show=ref(false),busy=ref(false),error=ref(''),form=ref({username:'',display_name:'',password:'',role:'viewer'})
async function load(){try{[rows.value,events.value]=await Promise.all([getJSON('/api/auth/users'),getJSON('/api/auth/events')]);error.value=''}catch(e){error.value=e.message}}
async function create(){busy.value=true;try{await postJSON('/api/auth/users',form.value);form.value={username:'',display_name:'',password:'',role:'viewer'};show.value=false;await load();ElMessage.success('账号已创建')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function save(row){try{await postJSON('/api/auth/users/'+row.id,{role:row.role,enabled:!!row.enabled});ElMessage.success('权限已更新，原登录会话已失效');await load()}catch(e){ElMessage.error(e.message);await load()}}
async function reset(row){try{const {value}=await ElMessageBox.prompt('设置至少 12 个字符的新密码，原登录会话将失效。','重置 '+row.username+' 的密码',{inputType:'password',inputValidator:v=>v?.length>=12||'密码至少 12 个字符'});await postJSON('/api/auth/users/'+row.id+'/password',{password:value});await load();ElMessage.success('密码已重置')}catch(e){if(e?.message)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">WORKSPACE ACCESS</div><h1>账号管理</h1><p>为不同职责分配权限，每一次操作都对应明确身份。</p></div><el-button type="primary" @click="show=true">＋ 创建账号</el-button></div><div class="role-grid"><article class="surface"><b>查看人员</b><p>查看设备、任务、图片和异常处理进度。</p></article><article class="surface"><b>巡检操作员</b><p>安排巡检、执行任务决策，处理告警并发起复检。</p></article><article class="surface"><b>管理员</b><p>拥有操作权限，可创建账号、调整角色和重置密码。</p></article></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="surface user-table"><h2>工作空间成员</h2><el-table :data="rows"><el-table-column prop="display_name" label="名称" min-width="150"/><el-table-column prop="username" label="用户名" min-width="130"/><el-table-column label="角色" width="175"><template #default="{row}"><el-select v-model="row.role"><el-option v-for="(n,k) in roleNames" :key="k" :value="k" :label="n"/></el-select></template></el-table-column><el-table-column label="启用" width="90"><template #default="{row}"><el-switch v-model="row.enabled" :active-value="1" :inactive-value="0"/></template></el-table-column><el-table-column label="操作" min-width="170"><template #default="{row}"><el-button link type="primary" @click="save(row)">保存权限</el-button><el-button link @click="reset(row)">重置密码</el-button></template></el-table-column></el-table></section><section class="surface user-table"><h2>账号操作记录</h2><el-table :data="events" max-height="360"><el-table-column prop="actor" label="操作人"/><el-table-column label="操作"><template #default="{row}">{{ actionNames[row.action]||row.action }}</template></el-table-column><el-table-column prop="target" label="目标账号"/><el-table-column label="说明"><template #default="{row}">{{ detailText(row.detail) }}</template></el-table-column><el-table-column label="时间" min-width="180"><template #default="{row}">{{ fmtTime(row.created_at) }}</template></el-table-column></el-table></section><el-dialog v-model="show" title="创建工作空间账号" width="430px"><el-form label-position="top" @submit.prevent="create"><el-form-item label="显示名称"><el-input v-model="form.display_name" maxlength="80"/></el-form-item><el-form-item label="用户名"><el-input v-model="form.username" maxlength="32" placeholder="3–32 位字母、数字或 . _ -"/></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password maxlength="128" autocomplete="new-password" placeholder="至少 12 个字符"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option v-for="(n,k) in roleNames" :key="k" :value="k" :label="n"/></el-select></el-form-item></el-form><template #footer><el-button @click="show=false">取消</el-button><el-button type="primary" :loading="busy" @click="create">创建账号</el-button></template></el-dialog></template>
<style scoped>.role-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:24px}.role-grid article{padding:23px}.role-grid b{font-size:14px;color:#4e6f48}.role-grid p{font-size:11px;color:#8a997d;line-height:1.9;margin:12px 0 0}.user-table{padding:24px;margin-bottom:24px}.user-table h2{font-size:15px;margin:0 0 20px}@media(max-width:800px){.role-grid{grid-template-columns:1fr}.user-table{padding:15px}}</style>
